import { createRequire } from 'node:module';
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const source=readFileSync('index.html','utf8').replace('requestAnimationFrame(frame);','window.__starfallTest={state:()=>({stage,wave,bossRound,enemies:enemies.length,bossHp:boss.hp,started,over}),clearWave:()=>{for(const e of [...enemies])hurtEnemy(e,1e9)},clearBoss:()=>hurtBoss(1e9)};requestAnimationFrame(frame);');
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1440,height:900},deviceScaleFactor:1});
await page.route('**/*',route=>route.fulfill({status:200,contentType:'text/html',body:source}));
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3000/',{waitUntil:'load',timeout:45000});
await page.locator('#startBtn').click({force:true});
const state=()=>page.evaluate(()=>window.__starfallTest.state());
console.log('started',await state());
for(let stageNo=1;stageNo<=3;stageNo++){
  for(let w=1;w<=2;w++){
    const s=await state();
    if(s.stage!==stageNo || s.bossRound || s.over) break;
    await page.evaluate(()=>window.__starfallTest.clearWave());
    await page.waitForTimeout(100);
    console.log('after wave clear',await state());
  }
  await page.waitForFunction(()=>window.__starfallTest.state().bossRound||window.__starfallTest.state().over,{timeout:5000}).catch(()=>{});
  let s=await state();
  if(s.over) break;
  if(!s.bossRound){console.log('FAILED: boss not triggered',s);break;}
  if(stageNo===1){
    const path='/tmp/opencode/starfall-captures/final-desktop.jpg';
    await page.screenshot({path,type:'jpeg',quality:76});
    console.log('saved latest JPEG',path,statSync(path).size);
  }
  await page.evaluate(()=>window.__starfallTest.clearBoss());
  console.log('after boss clear',await state());
  if(stageNo<3) await page.waitForTimeout(1100);
}
await page.waitForTimeout(700);
console.log('result visible',await page.locator('#result').evaluate(e=>!e.classList.contains('hidden')),'title',await page.locator('#resultTitle').innerText(),'errors',errors);
await browser.close();
